import urllib.request, json, urllib.parse, time
def get(u):
    time.sleep(1.2); return json.load(urllib.request.urlopen(u))
def q(term):
    return get("https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=pubmed&retmode=json&retmax=50&term="+urllib.parse.quote(term))["esearchresult"]["idlist"]
ids=set()
for t in ["Rash ER[Author]","Rash E[Author] AND Gallucci[Author]","Pickler MC[Author]","Gallucci AR[Author] AND (iron OR acrobatics)","acrobatics tumbling iron"]:
    r=q(t); print(t,r); ids|=set(r)
d=get("https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?db=pubmed&retmode=json&id="+",".join(ids))["result"]
for i in d.get("uids",[]):
    x=d[i]; au=", ".join(a["name"] for a in x["authors"])
    doi=[a["value"] for a in x.get("articleids",[]) if a["idtype"]=="doi"]
    print(i,x["pubdate"],x["source"],"|",x["title"][:140],"|",au[:200],"|",doi)

